    }
    case 'hi3': {
      const mod = await import('@gachia/data/games/hi3/characters');
      return mod.hi3Characters.map((character) => ({ id: character.id }));
    }
    case 'guihuan': {
      const mod = await import('@gachia/data/games/guihuan/characters');
