          const char = charMap.get(id);
          if (!char) return [];
          return [{ id: char.id, name: getAnantaCharacterName(char, locale), href: `/ananta/characters/${char.id}`, imageUrl: getAnantaCharacterImage(char), element: char.element, role: char.roleEn }];
